UPDATE inventories 
SET
	on_hand_qty = on_hand_qty + #{inboundQty},
	version = version + 1,
	updated_at = transaction_timestamp()
WHERE
	inventory_id = #{inventory.inventoryId}
	AND company_id = #{inventory.companyId}
	AND version = #{inventory.version}

